const mayor = (a, b) => {
  const x = a.split('.').map(Number), y = b.split('.').map(Number);
  for (let i = 0; i < 3; i++) {
    if (x[i] !== y[i]) return x[i] > y[i];
  }
  return false;
};
console.log('como texto, 1.10.0 > 1.9.0:', '1.10.0' > '1.9.0');
console.log('como números, 1.10.0 > 1.9.0:', mayor('1.10.0', '1.9.0'));
console.log('1.0.0 contra 1.0.0:', mayor('1.0.0', '1.0.0'));
